#include "../명명/기계연결이름.h"
/* Small native runtime for jaot's explicitly checked static Java subset. */
#include "호출.h"
#include "파일규약.h"
typedef unsigned long компьютер_Сөз;
static компьютер_Сөз 동적기억공간[8192];static unsigned 사용량;
void 자바실패(void){const char Мәтін[]="AOT runtime error\n";жазу_файл_деректер(2,Мәтін,sizeof(Мәтін)-1);사용자호출(6,1,0,0,0,0,0);for(;;){}}
void 자바쌓기(компьютер_Сөз *Бума_Жад,int *깊이,компьютер_Сөз мән){if(*깊이<0||*깊이>=128)자바실패();Бума_Жад[(*깊이)++]=мән;}
компьютер_Сөз 자바꺼내기(компьютер_Сөз *Бума_Жад,int *깊이){if(*깊이<=0||*깊이>128)자바실패();return Бума_Жад[--*깊이];}
компьютер_Сөз 자바배열(int 개수){if(개수<0||(unsigned)개수+1>8192-사용량)자바실패();компьютер_Сөз*деректер_лауазым=동적기억공간+사용량;사용량+=개수+1;деректер_лауазым[0]=개수;return (компьютер_Сөз)деректер_лауазым;}
компьютер_Сөз *자바색인(компьютер_Сөз нысан_Анықтамалық,int 개수){компьютер_Сөз*деректер_лауазым=(компьютер_Сөз*)нысан_Анықтамалық;if(!деректер_лауазым||개수<0||(компьютер_Сөз)개수>=деректер_лауазым[0])자바실패();return деректер_лауазым+개수+1;}
int 자바길이(компьютер_Сөз нысан_Анықтамалық){if(!нысан_Анықтамалық)자바실패();return *(компьютер_Сөз*)нысан_Анықтамалық;}
int 자바나누기(int x_координатасы,int Y_түймешігі_координата,int 나머지){if(!Y_түймешігі_координата)자바실패();if(x_координатасы==(-2147483647-1)&&Y_түймешігі_координата==-1)return 나머지?0:x_координатасы;return 나머지?x_координатасы%Y_түймешігі_координата:x_координатасы/Y_түймешігі_координата;}
static unsigned ұзындық_мән(const char*жол_деректер){unsigned 개수=0;if(!жол_деректер)자바실패();while(жол_деректер[개수])개수++;return 개수;}
void 자바출력(компьютер_Сөз деректер_лауазым,int 수치,int 줄바꿈){
    if(수치){char 둘째값[16];unsigned 개수=0;int мән=(int)деректер_лауазым;unsigned 부호없는값=мән<0?0-(unsigned)мән:мән;do{둘째값[개수++]='0'+부호없는값%10;부호없는값/=10;}while(부호없는값);if(мән<0)둘째값[개수++]='-';while(개수)жазу_файл_деректер(1,둘째값+--개수,1);}
    else{const char*жол_деректер=деректер_лауазым?(const char*)деректер_лауазым:"null";жазу_файл_деректер(1,жол_деректер,ұзындық_мән(жол_деректер));}if(줄바꿈)жазу_файл_деректер(1,"\n",1);
}
компьютер_Сөз 자바파일쓰기(компьютер_Сөз Жол_2,компьютер_Сөз мән){const char*жол_деректер=(const char*)мән;unsigned 개수=ұзындық_мән(жол_деректер);int файл_дескриптор=ашу_файл((const char*)Жол_2,쓰기전용|없으면만들기|қысқарту_Мазмұны,0600);if(файл_дескриптор<0)자바실패();int 반환값=жазу_файл_деректер(файл_дескриптор,жол_деректер,개수);Жабу_файл(файл_дескриптор);if(반환값!=(int)개수)자바실패();return 0;}
компьютер_Сөз 자바파일읽기(компьютер_Сөз Жол_2){int файл_дескриптор=ашу_файл((const char*)Жол_2,тек_оқу_үшін_мән,0);if(файл_дескриптор<0)자바실패();int 개수=файл_өлшемі(файл_дескриптор);if(개수<0||개수>16384||(unsigned)(개수+8)/8>8192-사용량)자바실패();char*деректер_лауазым=(char*)(동적기억공간+사용량);사용량+=(개수+8)/8;int 반환값=파일자료읽기(файл_дескриптор,деректер_лауазым,개수);Жабу_файл(файл_дескриптор);if(반환값!=개수)자바실패();деректер_лауазым[개수]=0;return (компьютер_Сөз)деректер_лауазым;}
